import random, math
from collections import deque
E=[((1,2,0,0),3,3,4,(3,2,1),6),((1,0,0,3),3,3,9,(4,1,3),11),((1,0,0,1),1,1,3,(3,1,3),3),((1,0,0,1),2,1,8,(2,1,3),7)]
def nexts(s,G,C,M,c):
 m,g,d,e=s
 if m<C and e>=c[0]:yield 0,(m+1,g,d,e-c[0])
 if m and g<C and e>=c[1]:yield 1,(m-1,g+1,d,e-c[1])
 if g and e>=c[2]:yield 2,(m,g-1,d+1,e-c[2])
 if e<M:yield 3,(m,g,d,M)
def run(ex,w,ret=False):
 s,G,C,M,c,_=ex;r=w[:6];a=w[6:];path=[]
 def score(t,p):return r[0]*t[2]/G+r[1]*(t[2]>=G)-r[2]*len(p)+r[3]*t[3]/M+r[4]*t[0]/C+r[5]*t[1]/C+sum(a[x] for x in p)
 for step in range(16):
  if s[2]>=G:return path if ret else step
  frontier={s:()};ends=[]
  for dep in range(3):
   nf={}
   for t,p in frontier.items():
    for x,u in nexts(t,G,C,M,c):
     q=p+(x,)
     if u[2]>=G:ends.append((score(u,q),u,q));continue
     if u not in nf or score(u,q)>score(u,nf[u]):nf[u]=q
   frontier=dict(sorted(nf.items(),key=lambda z:score(*z),reverse=True)[:48])
  ends.extend((score(t,p),t,p) for t,p in frontier.items())
  if not ends:return 99
  _,_,p=max(ends,key=lambda z:z[0]);x=p[0];s=dict(nexts(s,G,C,M,c))[x];path.append(x)
 return path if ret else (16 if s[2]>=G else 99)
random.seed(7)
best=99
for i in range(12000):
 w=[random.uniform(3,9),random.uniform(3,9),random.uniform(.1,3),random.uniform(0,3),random.uniform(0,3),random.uniform(0,4)]+[random.uniform(-2,0) for _ in range(4)]
 loss=sum(abs(run(e,w)-e[-1]) for e in E)
 if loss<best:
  best=loss;print(best,w,flush=True)
 if loss==0:
  print('paths',[run(e,w,True) for e in E]);break
PY"

